import List from '@mui/material/List';
import ListItem from '@mui/material/ListItem';
import ListItemAvatar from '@mui/material/ListItemAvatar';
import ListItemText from '@mui/material/ListItemText';

import Box from '@mui/material/Box';

import LanguageIcon from '@mui/icons-material/Language';
import { IconButton } from '@mui/material';

export default function Contact() {
    const items= [
        {
        title: "Fxns",
        description: "Description",
        src: "https://fxns.com",
        },
        {
        title: "IdeaBurn",
        description: "Idea sharing platform",
        src: "https://www.youtube.com/embed/aFiUmvcF3Xw?si=RbzuFhUhqu5qPJsA",
        },
        {
        title: "Mohawk College",
        description: "PHP Demonstrations",
        src: "https://www.youtube.com/embed/videoseries?list=PLh17cpqc5tdWh_b2x-6Am0r08BeYy0H2g",
        },
        {
        title: "Mohawk College",
        description: "Mohawk College Tech Presentations",
        src: "https://www.youtube.com/embed/videoseries?list=PLh17cpqc5tdUla07BUe_gP5kNb0sowuh_",
        },
    ];

    return (
        <>
        <List dense={false}>
            {items.map((item, index) => (
        <ListItem
          key={index}
          sx={{
            backgroundColor: index % 2 === 0 ? "#f9f9f9" : "#eaeaea", // Alternate background colors
            borderRadius: "8px",
            marginBottom: "16px",
          }}
        >
          <ListItemAvatar>
            <IconButton 
              component="a" // Make the IconButton behave like a link
              href={item.src} // Navigate to the URL specified in the `src` property
              target="_blank" // Open the link in a new tab
              rel="noopener noreferrer"
            >
              <LanguageIcon />
            </IconButton>
          </ListItemAvatar>
          <ListItemText primary={item.title} secondary={item.description} />
        </ListItem>
        ))}
        </List>
        </>
    )
}
